commands.command:
install -d -o nginx -g nginx /var/www/inventory
cat > /var/www/inventory/index.html <<'INVENTORY_HTML'
<!doctype html>
<html><head><meta charset="utf-8"><title>Inventory</title></head>
<body><h1>Inventory Web Application</h1><p>Served by <strong>node2</strong></p>
<table border="1"><thead><tr><th>SKU</th><th>Item</th><th>Quantity</th></tr></thead>
<tbody><tr><td>SKU-1001</td><td>Alpine Widget</td><td>42</td></tr>
<tr><td>SKU-1002</td><td>Load Balancer Kit</td><td>18</td></tr>
<tr><td>SKU-1003</td><td>Network Cable</td><td>96</td></tr></tbody></table></body></html>
INVENTORY_HTML
chown nginx:nginx /var/www/inventory/index.html
cat > /etc/nginx/http.d/default.conf <<'NGINX_CONF'
server {
    listen 8080 default_server;
    listen [::]:8080 default_server;
    server_name _;
    root /var/www/inventory;
    index index.html;
    add_header X-Inventory-Backend node2 always;

    location = /health {
        default_type application/json;
        return 200 '{"status":"ok","backend":"node2"}';
    }

    location / {
        try_files $uri $uri/ =404;
    }
}
NGINX_CONF
nginx -t

install -d -o nginx -g nginx /var/www/inventory
cat > /var/www/inventory/index.html <<'INVENTORY_HTML'
<!doctype html>
<html><head><meta charset="utf-8"><title>Inventory</title></head>
<body><h1>Inventory Web Application</h1><p>Served by <strong>node3</strong></p>
<table border="1"><thead><tr><th>SKU</th><th>Item</th><th>Quantity</th></tr></thead>
<tbody><tr><td>SKU-1001</td><td>Alpine Widget</td><td>42</td></tr>
<tr><td>SKU-1002</td><td>Load Balancer Kit</td><td>18</td></tr>
<tr><td>SKU-1003</td><td>Network Cable</td><td>96</td></tr></tbody></table></body></html>
INVENTORY_HTML
chown nginx:nginx /var/www/inventory/index.html
cat > /etc/nginx/http.d/default.conf <<'NGINX_CONF'
server {
    listen 8080 default_server;
    listen [::]:8080 default_server;
    server_name _;
    root /var/www/inventory;
    index index.html;
    add_header X-Inventory-Backend node3 always;

    location = /health {
        default_type application/json;
        return 200 '{"status":"ok","backend":"node3"}';
    }

    location / {
        try_files $uri $uri/ =404;
    }
}
NGINX_CONF
nginx -t

cat > /etc/nginx/http.d/default.conf <<'NGINX_CONF'
upstream inventory_backends {
    server 10.100.54.11:8080 max_fails=2 fail_timeout=5s;
    server 10.100.54.12:8080 max_fails=2 fail_timeout=5s;
    keepalive 16;
}

server {
    listen 80 default_server;
    listen [::]:80 default_server;
    server_name _;

    location / {
        proxy_pass http://inventory_backends;
        proxy_http_version 1.1;
        proxy_set_header Connection "";
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_next_upstream error timeout http_502 http_503 http_504;
        add_header X-Selected-Upstream $upstream_addr always;
    }
}
NGINX_CONF
nginx -t

